@push('scripts')<script>$(function(){var $t=$('#employee-advances-table'),text=$.fn.dataTable.render.text(),labels={DRAFT:'ร่าง',SUBMITTED:'รออนุมัติ',APPROVED:'อนุมัติแล้ว',POSTED:'ลงบัญชีแล้ว',PARTIAL:'ตัดบางส่วน',CLEARED:'เคลียร์แล้ว',VOID:'ยกเลิก',REVERSED:'ยกเลิกรายการแล้ว'};var table=$t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:$t.data('url'),data:function(d){d.status=$('#employee-advance-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton($t)],columns:[{data:'document_number',render:text.display},{data:'document_date_label',render:text.display},{data:'employee_label',render:text.display},{data:'bank_account_label',render:text.display},{data:'amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status_label',render:function(v,type,row){return type==='display'?'<span class="badge '+text.display(row.status_class||'app-status-neutral')+'">'+text.display(v||labels[row.status]||row.status)+'</span>':v;}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(_,type,row){if(type!=='display')return '';var html='<a class="btn btn-sm btn-app-soft" href="'+text.display(row.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>';if(row.edit_url)html+=' <a class="btn btn-sm btn-app-soft" href="'+text.display(row.edit_url)+'" title="แก้ไข" aria-label="แก้ไข"><i class="bx bx-edit" aria-hidden="true"></i></a>';return html;}}]}));$('#employee-advance-status').on('change',function(){table.ajax.reload();});$('#employee-advance-reset').on('click',function(){$('#employee-advance-status').val('');table.ajax.reload();});});</script>@endpush
